<div style={{ display: "flex", gap: "6px", flexWrap: "wrap", alignItems: "center" } as any}><b style={{ font: "700 14px 'Helvetica Neue',Helvetica,Arial", marginRight: "4px" } as any}>Upcoming PI event</b>{(v.sus.evs || []).map((v: any, v_n: number) => (<Fragment key={v_n}><button onClick={v.go} style={{ cursor: "pointer", padding: "5px 12px", borderRadius: "99px", border: "2px solid #0d1815", background: `${v.bg}`, color: `${v.fg}`, font: "700 12.5px 'Helvetica Neue',Helvetica,Arial" } as any}>{v.v}</button></Fragment>))}{v.sus.evOther ? (<><input key={v.sus.evK} defaultValue={v.sus.evTxt} onBlur={v.sus.setEvTxt} placeholder="Which event?" style={{ all: "unset", borderBottom: "1.5px dashed #0d181888", padding: "4px 2px", font: "600 14px 'Helvetica Neue',Helvetica,Arial", minWidth: "160px" } as any} /></>) : null}</div>
